class Luhn:
    def __init__(self, card_num):
        self.card_num = card_num

    def valid(self):
        if not isinstance(self.card_num, str):
            return False
        normalized = self.card_num.replace(" ", "")
        # Strings of length 1 or less are not valid.
        if len(normalized) <= 1:
            return False
        # All non-digit characters are disallowed.
        if not normalized.isdigit():
            return False

        total = 0
        # Process digits from right to left; double every second digit (positions 1,3,5,...)
        for idx, ch in enumerate(reversed(normalized)):
            digit = int(ch)
            if idx % 2 == 1:
                digit *= 2
                if digit > 9:
                    digit -= 9
            total += digit

        return total % 10 == 0
